def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    shortest_path = [0]*N
    second_shortest_path = [0]*N

    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                shortest_path[j] = second_shortest_path[j] = grid_values[i][2]
                continue
            if i == 0:
                shortest_path[j] = shortest_path[j-1] + grid_values[i][2]
                second_shortest_path[j] = second_shortest_path[j-1]
            elif j == 0:
                shortest_path[j] = shortest_path[j] + grid_values[i][2]
                second_shortest_path[j] = second_shortest_path[j-1]
            else:
                shortest_path[j] = max(shortest_path[j-1], second_shortest_path[j-1]) + grid_values[i][2]
                second_shortest_path[j] = min(shortest_path[j-1], second_shortest_path[j-1]) + grid_values[i][2]

    return max(shortest_path[N-1], second_shortest_path[N-1])

