def verify_isbn(isbn: str) -> str:
    if len(isbn) != 12 and isbn != 'X':
        return "Error: The ISBN number must be exactly 12 digits."

    # Remove any '-' character
    isbn = isbn.replace('-', '')

    # Calculate the correct ISBN checksum
    def calculate_isbn_checksum(isbn):
        if isbn.endswith('X'):
            isbn = isbn[:-1] + '10'
        total = sum((int(digit) or 10) * (2 ** index) for index, digit in enumerate(reversed(isbn)))
        return str((total % 11) % 11).upper()

    calculated_checksum = calculate_isbn_checksum(isbn)

    if calculated_checksum == isbn[11]:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + calculated_checksum
        return corrected_isbn

def verify_isbn(isbn: str) -> str:
    if not isbn.replace('-', '').isdigit():
        raise ValueError("ISBN number must contain only digits and hyphens.")

    check_digit = check_isbn_checksum(isbn)
    if check_digit == 'X':
        check_digit = chr(87)  # 'X' represented as 'x' in ASCII

    if isbn[-1] == check_digit:
        return "Right"
    else:
        correction_position = int(isbn[-1]) - int(check_digit)
        corrected_isbn = isbn[:-1] + chr(ord(isbn[-1]) - (2 * correction_position) % 10)
        return corrected_isbn

def verify_isbn(isbn: str) -> str:
    def checksum(isbn: str) -> int:
        digits = [int(d) for d in isbn] + [10 if isbn[-1] == 'X' else int(isbn[-1])]
        return sum(d * (3 if i % 2 == 0 else 1) for i, d in enumerate(digits))

    corrected_isbn = isbn
    if checksum(isbn) != 10:
        # Calculate the correct checksum digit
        correct_checksum = 10 - checksum(isbn)
        # Replace the last digit with the correct checksum digit
        corrected_isbn = isbn[:-1] + chr(correct_checksum + ord('0'))

    return "Right" if checksum(corrected_isbn) == 10 else corrected_isbn

