        res[i] = res[i - 1] + (n - 1) * (res[i - 1] // 2)

    return res[-1]

def count_passing_ways(n, m):
    # Initialize the dp table where dp[i][j] represents the number of ways 
    # student i has not passed any ball to student j after m passes.
    # Initial state: dp[i][i] = 1 for all i where i is a student number
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1

    # Dynamic programming for passing the ball efficiently
    for j in range(2, m + 1):
        for i in range(n):
            # Using only one pass from the right to the left or 
            # one pass from the left to the right
            dp[i][j] = j * (dp[(i - 1) % n][j - 1]) + j * (dp[(i + 1) % n][j - 1])

    # The final result is the sum of all ways that the ball returns to the starting student
    return sum(dp[0]) % (10**9 + 7)

