    for i in range(len(encoded)):
        if encoded[i] not in letter_mapping or original[i] != letter_mapping[encoded[i]]:
            return "Failed"
        letter_mapping[encoded[i]] = original[i]

    # Check if all letters are represented in the mapping
    if len(letter_mapping) != len(set(original)):
