def count_partitions(n: int, k: int, x: int) -> int:
    # Handle edge cases where n is less than k or k is less than 1
    if n < k or k < 1:
        return 0

    # Helper function to calculate combination of n taken k at a time
    def combination(n, k):
        if k > n // 2:
            k = n - k
        result = 1
        for i in range(1, k + 1):
            result *= n - i + 1
            result //= i
        return result

    # Calculate number of partitions considering the minimum part requirement
    total_partitions = 0
    for i in range(x, n + 1):
        remaining_sum = n - i
        remaining_parts = k - 1
        total_partitions += combination(remaining_sum, remaining_parts) * combination(i - 1, i - k)

    return total_partitions

def count_partitions(n: int, k: int, x: int) -> int:
    # Check for invalid inputs
    if not (isinstance(n, int) and isinstance(k, int) and isinstance(x, int) and n > 0 and k > 0 and x > 0):
        raise ValueError("Input parameters must be non-negative integers and n must be greater than 0")

    # Recursive function to count partitions
    def count_partitionsRecursive(n, k, x, partition):
        if k == 0:
            if n == 0:
                return 1
            else:
                return 0
        if n < x * k:
            return 0
        partition.append(x)
        count = count_partitionsRecursive(n - x, k - 1, x, partition)
        partition.pop()
        return count + count_partitionsRecursive(n, k, x + 1, partition)

    partition = []
    return count_partitionsRecursive(n, k - 1, x, partition) * k

def count_partitions(n, k, x):
    if k == 1:
        return 1 if n >= x else 0
