    memo = [[0 for _ in range(k+1)] for _ in range(n+1)]
    for i in range(n+1):
        memo[i][1] = i // x + 1  # Base case: one part, all parts x
        for j in range(2, k+1):
            for l in range(x, n-j*x+1):
                memo[l][j] = memo[l-x][j] + memo[l-j*x][j-1]
    return memo[n][k]

