            return value
        # Include the current herb and calculate the value
        include_value = choose_ herbs(index + 1, time + herbs[index][0], value + herbs[index][1])
        # Exclude the current herb and move to the next
        exclude_value = choose_ herbs(index + 1, time, value)
        return max(include_value, exclude_value)

    # Initialize with default values
    result = choose_ herbs(0, 0, 0)
    return result

