def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0:
        raise ValueError("Invalid input: Time cannot be negative, and number of herbs cannot be negative.")

    if T == 0 or M == 0:
        return 0

    dp = [[0] * (M+1) for _ in range(T+1)]

    for i, (time, value) in enumerate(herbs, start=1):
        for j in range(T+1):
            dp[j][i] = dp[j][i-1]
            if j >= time:
                dp[j][i] = max(dp[j][i], dp[j-time][i-1] + value)

    return dp[T][M]

