def max_herb_value_iter(T: int, cur_time: int, val: int, herbs: Dict[int, int]) -> int:
    if cur_time > T:
        return val
    max_val = val
    for herb_time in herbs:
        if herb_time <= cur_time:
            max_val = max(max_val, herb_val + max_herb_value_iter(T, cur_time + herb_time, val + herb_val, herbs))
    return max_val

