def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    def holds(V, i):
        return V >= volumes[i]

    def rec(V, i):
        if i == n or V == 0:
            return 0
        if holds(V, i):
            return max(holds(V - volumes[i], i) + rec(V - volumes[i], i), rec(V, i + 1))
        else:
            return rec(V, i + 1)

    return V - rec(V, 0)

