    if V < min(volumes) or max(volumes) > V:
        return -1

    # Initialize the dynamic programming table with	Ints as 0
    dp = [[0 for _ in range(V + 1)] for _ in range(n + 1)]

    # Base case: If there are no items, the maximum volume is 0
    for volume in range(V + 1):
        dp[0][volume] = 0

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                # Include the current item if it can fit
                dp[i][j] = max(volumes[i - 1] + dp[i - 1][j - volumes[i - 1]], dp[i - 1][j])
            else:
                # Exclude the current item if it can't fit
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the total capacity minus the maximum occupied volume
    return V - dp[n][V]

