        for j in range(1, m + 1):
            if j >= a[i - 1]:
                dp[j] = (dp[j] + prev[j - a[i - 1]]) % MOD
            else:
                dp[j] = prev[j]

    return dp[m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    # Validate input parameters
    if not isinstance(key, str) or not isinstance(ciphertext, str):
        raise ValueError("Both key and ciphertext must be strings")
    if not all(char.isalpha() for char in key) or not all(char.isalpha() for char in ciphertext):
        raise ValueError("Key and ciphertext must consist only of alphabetic characters")

    # Adjust key length to fit the ciphertext length and handle circular shifts
    key_length = len(key)
    ciphertext_length = len(ciphertext)
    if key_length < ciphertext_length:
        extended_key = key * int((ciphertext_length - key_length) // key_length) + key[:ciphertext_length % key_length]
    elif key_length > ciphertext_length:
        extended_key = key[:ciphertext_length]

    # Decrypt the ciphertext
    decrypted plaintext = ""
    for i, char in enumerate(ciphertext):
        # Calculate shift amount based on the key character
        shift = ord(key[i % key_length]) - ord('A')
        # Decrypt by shifting the character back by the shift amount
        if char.islower():
            decrypted_char = chr((ord(char) - ord('a') - shift + 26) % 26 + ord('a'))
        else:
            decrypted_char = chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
        decrypted plaintext += decrypted_char

    return decrypted plaintext

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c: str, shift: int) -> str:
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        return c

    n = len(ciphertext)
    decrypted = ""
    key_length = len(key)
    key_extended = key * (n // key_length) + key[:n % key_length]

    for i in range(n):
        letter = ciphertext[i]
        key_char = key_extended[i]
        decrypted += shift_char(letter, -ord(key_char) % 26)

    return decrypted

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not all(char.isalpha() for char in key + ciphertext):
        raise ValueError("Key and ciphertext should consist only of alphabetic characters")

    text_length = max(len(key), len(ciphertext))
    key = key * (text_length // len(key)) + key[:text_length % len(key)]
    decrypted_text = []

    for i in range(text_length):
        original_char = ciphertext[i]
        shift = ord(key[i]) - ord('A')
        if original_char.isupper():
            decrypted_char = chr(((ord(original_char) - ord('A') - shift) % 26) + ord('A'))
        else:
            decrypted_char = chr(((ord(original_char) - ord('a') - shift) % 26) + ord('a'))
        decrypted_text.append(decrypted_char)

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    if b == 0:
        return None

    x1, x2 = 0, 1
    y1, y2 = 1, 0

    while b != 0:
        q = a // b
        a, b = b, a % b
        x1, x2 = x2 - q * x1, x1
        y1, y2 = y2 - q * y2, y2

    if x1 < 0:
        x1 += b

    return x1

def mod_inverse(a, b):
    if a <= 0 or b <= 0:
        raise ValueError("A and B must be positive integers.")
    if not (a % b == 0):
        return None

    x, y = 0, 1
    while b != 0:
        quotient = a // b
        x, y = y, (x - quotient * y)
        a, b = b, a - quotient * b

    return x % b

